experiments.command:
node --input-type=module <<'JS'
import { chromium } from '/opt/browser/node_modules/playwright-core/index.mjs';
import { spawn } from 'node:child_process';
import { readFile } from 'node:fs/promises';
const png = await readFile('button-finish.png');
for(let p=8;p<png.length;){const n=png.readUInt32BE(p); const type=png.toString('ascii',p+4,p+8); console.log(type,n, type==='acTL'||type==='fcTL'?png.subarray(p+8,p+8+n).toString('hex'):'');p+=12+n;}
const server=spawn(process.execPath,['server.mjs'],{stdio:'ignore'});
let browser;
try {
for(let i=0;i<100;i++){try{if((await fetch('http://127.0.0.1:8080/')).ok)break;}catch{}await new Promise(r=>setTimeout(r,50));}
browser=await chromium.launch({executablePath:'/usr/bin/chromium',args:['--no-sandbox','--disable-dev-shm-usage']});
const page=await browser.newPage({viewport:{width:1040,height:850}});
await page.goto('http://127.0.0.1:8080/');
await page.waitForTimeout(6000);
await page.screenshot({path:'/tmp/delayed.png',fullPage:true});
await page.setViewportSize({width:390,height:844});
await page.screenshot({path:'/tmp/mobile.png',fullPage:true});
}finally{await browser?.close();server.kill();}
JS

